ISO_27001_2022_CONTROLS = [
    # Theme 5: Organizational Controls
    {"id": "5.1", "theme": "Organizational Controls", "name": "Policies for information security", "desc": "Information security policy and topic-specific policies shall be defined, approved by management, published, communicated to and acknowledged by relevant personnel and relevant interested parties, and reviewed at planned intervals and if significant changes occur."},
    {"id": "5.2", "theme": "Organizational Controls", "name": "Information security roles and responsibilities", "desc": "Information security roles and responsibilities shall be defined and allocated according to the organization needs."},
    {"id": "5.3", "theme": "Organizational Controls", "name": "Segregation of duties", "desc": "Conflicting duties and conflicting areas of responsibility shall be segregated."},
    {"id": "5.4", "theme": "Organizational Controls", "name": "Management responsibilities", "desc": "Management shall require all personnel to apply information security in accordance with the established information security policy, topic-specific policies and procedures of the organization."},
    {"id": "5.5", "theme": "Organizational Controls", "name": "Contact with authorities", "desc": "The organization shall establish and maintain contact with relevant authorities."},
    {"id": "5.6", "theme": "Organizational Controls", "name": "Contact with special interest groups", "desc": "The organization shall establish and maintain contact with special interest groups or other specialist security forums and professional associations."},
    {"id": "5.7", "theme": "Organizational Controls", "name": "Threat intelligence", "desc": "Information relating to information security threats shall be collected and analysed to produce threat intelligence."},
    {"id": "5.8", "theme": "Organizational Controls", "name": "Information security in project management", "desc": "Information security shall be integrated into project management."},
    {"id": "5.9", "theme": "Organizational Controls", "name": "Inventory of information and other associated assets", "desc": "An inventory of information and other associated assets, including owners, shall be developed and maintained."},
    {"id": "5.10", "theme": "Organizational Controls", "name": "Acceptable use of information and other associated assets", "desc": "Rules for the acceptable use and procedures for handling information and other associated assets shall be identified, documented and implemented."},
    {"id": "5.11", "theme": "Organizational Controls", "name": "Return of assets", "desc": "Personnel and other interested parties as appropriate shall return all the organization's assets in their possession upon change or termination of their employment, contract or agreement."},
    {"id": "5.12", "theme": "Organizational Controls", "name": "Classification of information", "desc": "Information shall be classified according to the information security needs of the organization based on confidentiality, integrity, availability and relevant interested party requirements."},
    {"id": "5.13", "theme": "Organizational Controls", "name": "Labelling of information", "desc": "An appropriate set of procedures for information labelling shall be developed and implemented in accordance with the information classification scheme adopted by the organization."},
    {"id": "5.14", "theme": "Organizational Controls", "name": "Information transfer", "desc": "Information transfer rules, procedures, or agreements shall be in place for all types of transfer facilities within the organization and between the organization and other parties."},
    {"id": "5.15", "theme": "Organizational Controls", "name": "Access control", "desc": "Rules to control physical and logical access to information and other associated assets shall be established and implemented based on business and information security requirements."},
    {"id": "5.16", "theme": "Organizational Controls", "name": "Identity management", "desc": "The full life cycle of identities shall be managed."},
    {"id": "5.17", "theme": "Organizational Controls", "name": "Authentication information", "desc": "Allocation and management of authentication information shall be controlled by a management process, including advising personnel on the appropriate handling of authentication information."},
    {"id": "5.18", "theme": "Organizational Controls", "name": "Access rights", "desc": "Access rights to information and other associated assets shall be provisioned, reviewed, modified and removed in accordance with the organization’s topic-specific policy on and rules for access control."},
    {"id": "5.19", "theme": "Organizational Controls", "name": "Information security in supplier relationships", "desc": "Processes and procedures shall be defined and implemented to manage the information security risks associated with the use of supplier's products or services."},
    {"id": "5.20", "theme": "Organizational Controls", "name": "Addressing information security within supplier agreements", "desc": "Relevant information security requirements shall be established and agreed with each supplier based on the type of supplier relationship."},
    {"id": "5.21", "theme": "Organizational Controls", "name": "Managing information security in the ICT supply chain", "desc": "Processes and procedures shall be defined and implemented to manage the information security risks associated with the ICT products and services supply chain."},
    {"id": "5.22", "theme": "Organizational Controls", "name": "Monitoring, review and change management of supplier services", "desc": "The organization shall regularly monitor, review, evaluate and manage change in supplier information security practices and service delivery."},
    {"id": "5.23", "theme": "Organizational Controls", "name": "Information security for use of cloud services", "desc": "Processes for acquisition, use, management and exit from cloud services shall be established in accordance with the organization’s information security requirements."},
    {"id": "5.24", "theme": "Organizational Controls", "name": "Information security incident management planning and preparation", "desc": "The organization shall plan and prepare for managing information security incidents by defining, establishing and communicating information security incident management processes, roles and responsibilities."},
    {"id": "5.25", "theme": "Organizational Controls", "name": "Assessment and decision on information security events", "desc": "The organization shall assess information security events and decide if they are to be categorized as information security incidents."},
    {"id": "5.26", "theme": "Organizational Controls", "name": "Response to information security incidents", "desc": "Information security incidents shall be responded to in accordance with the documented procedures."},
    {"id": "5.27", "theme": "Organizational Controls", "name": "Learning from information security incidents", "desc": "Knowledge gained from information security incidents shall be used to improve and strengthen the information security management system."},
    {"id": "5.28", "theme": "Organizational Controls", "name": "Collection of evidence", "desc": "The organization shall establish and implement procedures for the identification, collection, acquisition and preservation of evidence related to information security events."},
    {"id": "5.29", "theme": "Organizational Controls", "name": "Information security during disruption", "desc": "The organization shall plan how to maintain information security at an appropriate level during disruption."},
    {"id": "5.30", "theme": "Organizational Controls", "name": "ICT readiness for business continuity", "desc": "ICT readiness shall be planned, implemented, maintained and tested based on business continuity objectives and ICT continuity requirements."},
    {"id": "5.31", "theme": "Organizational Controls", "name": "Legal, statutory, regulatory and contractual requirements", "desc": "Legal, statutory, regulatory and contractual requirements relevant to information security and the organization's approach to meet these requirements shall be identified, documented and kept up to date."},
    {"id": "5.32", "theme": "Organizational Controls", "name": "Intellectual property rights", "desc": "The organization shall implement appropriate procedures to protect intellectual property rights."},
    {"id": "5.33", "theme": "Organizational Controls", "name": "Protection of records", "desc": "Records shall be protected from loss, destruction, falsification, unauthorized access and unauthorized release."},
    {"id": "5.34", "theme": "Organizational Controls", "name": "Privacy and protection of PII", "desc": "The organization shall identify and meet the requirements regarding the preservation of privacy and protection of personally identifiable information (PII) according to applicable laws and regulations and contractual requirements."},
    {"id": "5.35", "theme": "Organizational Controls", "name": "Independent review of information security", "desc": "The organization’s approach to managing information security and its implementation shall be reviewed independently at planned intervals or when significant changes occur."},
    {"id": "5.36", "theme": "Organizational Controls", "name": "Compliance with policies, rules and standards", "desc": "Managers shall regularly review compliance of information processing and procedures within their area of responsibility with the appropriate security policies, rules and standards of the organization."},
    {"id": "5.37", "theme": "Organizational Controls", "name": "Documented operating procedures", "desc": "Operating procedures for information processing facilities shall be documented and made available to personnel who need them."},

    # Theme 6: People Controls
    {"id": "6.1", "theme": "People Controls", "name": "Screening", "desc": "Background verification checks on all candidates to become personnel shall be carried out prior to joining the organization and on an ongoing basis."},
    {"id": "6.2", "theme": "People Controls", "name": "Terms and conditions of employment", "desc": "The employment contractual agreements shall state the personnel's and the organization's responsibilities for information security."},
    {"id": "6.3", "theme": "People Controls", "name": "Information security awareness, education and training", "desc": "Personnel of the organization and relevant interested parties shall receive appropriate information security awareness, education and training."},
    {"id": "6.4", "theme": "People Controls", "name": "Disciplinary process", "desc": "A disciplinary process shall be formalized and communicated to take action against personnel and other relevant interested parties who have committed an information security policy violation."},
    {"id": "6.5", "theme": "People Controls", "name": "Responsibilities after termination or change of employment", "desc": "Information security responsibilities and duties that remain valid after termination or change of employment shall be defined, enforced and communicated to relevant personnel and other interested parties."},
    {"id": "6.6", "theme": "People Controls", "name": "Confidentiality or non-disclosure agreements", "desc": "Confidentiality or non-disclosure agreements reflecting the organization's needs for the protection of information shall be identified, documented, regularly reviewed and signed by personnel and other relevant interested parties."},
    {"id": "6.7", "theme": "People Controls", "name": "Remote working", "desc": "Security measures shall be implemented when personnel are working remotely to protect information accessed, processed or stored outside the organization’s premises."},
    {"id": "6.8", "theme": "People Controls", "name": "Information security event reporting", "desc": "The organization shall provide a mechanism for personnel to report observed or suspected information security events through appropriate channels in a timely manner."},

    # Theme 7: Physical Controls
    {"id": "7.1", "theme": "Physical Controls", "name": "Physical security perimeters", "desc": "Security perimeters shall be defined and used to protect areas that contain information and other associated assets."},
    {"id": "7.2", "theme": "Physical Controls", "name": "Physical entry", "desc": "Secure areas shall be protected by appropriate entry controls and access points."},
    {"id": "7.3", "theme": "Physical Controls", "name": "Securing offices, rooms and facilities", "desc": "Physical security for offices, rooms and facilities shall be designed and implemented."},
    {"id": "7.4", "theme": "Physical Controls", "name": "Physical security monitoring", "desc": "Premises shall be continuously monitored for unauthorized physical access."},
    {"id": "7.5", "theme": "Physical Controls", "name": "Protecting against physical and environmental threats", "desc": "Protection against physical and environmental threats, such as natural disasters and other intentional or unintentional physical threats to infrastructure shall be designed and implemented."},
    {"id": "7.6", "theme": "Physical Controls", "name": "Working in secure areas", "desc": "Security measures for working in secure areas shall be designed and implemented."},
    {"id": "7.7", "theme": "Physical Controls", "name": "Clear desk and clear screen", "desc": "Clear desk rules for papers and removable storage media and clear screen rules for information processing facilities shall be defined and appropriately enforced."},
    {"id": "7.8", "theme": "Physical Controls", "name": "Equipment siting and protection", "desc": "Equipment shall be sited securely and protected."},
    {"id": "7.9", "theme": "Physical Controls", "name": "Security of assets off-premises", "desc": "Off-site assets shall be protected."},
    {"id": "7.10", "theme": "Physical Controls", "name": "Storage media", "desc": "Storage media shall be managed through their life cycle of acquisition, use, transportation and disposal in accordance with the organization’s classification scheme and handling requirements."},
    {"id": "7.11", "theme": "Physical Controls", "name": "Supporting utilities", "desc": "Information processing facilities shall be protected from power failures and other disruptions caused by failures in supporting utilities."},
    {"id": "7.12", "theme": "Physical Controls", "name": "Cabling security", "desc": "Cabling carrying power, data or supporting information services shall be protected from interception, interference or damage."},
    {"id": "7.13", "theme": "Physical Controls", "name": "Equipment maintenance", "desc": "Equipment shall be maintained correctly to ensure availability, integrity and confidentiality of information."},
    {"id": "7.14", "theme": "Physical Controls", "name": "Secure disposal or re-use of equipment", "desc": "Items of equipment containing storage media shall be verified to ensure that any sensitive data and licensed software has been removed or securely overwritten prior to disposal or re-use."},

    # Theme 8: Technological Controls
    {"id": "8.1", "theme": "Technological Controls", "name": "User endpoint devices", "desc": "Information stored on, processed by or accessible via user endpoint devices shall be protected."},
    {"id": "8.2", "theme": "Technological Controls", "name": "Privileged access rights", "desc": "The allocation and use of privileged access rights shall be restricted and managed."},
    {"id": "8.3", "theme": "Technological Controls", "name": "Information access restriction", "desc": "Access to information and other associated assets shall be restricted in accordance with the established topic-specific policy on access control."},
    {"id": "8.4", "theme": "Technological Controls", "name": "Access to source code", "desc": "Read and write access to source code, development tools and software libraries shall be appropriately managed."},
    {"id": "8.5", "theme": "Technological Controls", "name": "Secure authentication", "desc": "Secure authentication technologies and procedures shall be implemented based on information access restrictions and the topic-specific policy on access control."},
    {"id": "8.6", "theme": "Technological Controls", "name": "Capacity management", "desc": "The use of resources shall be monitored and adjusted in line with current and expected capacity requirements."},
    {"id": "8.7", "theme": "Technological Controls", "name": "Protection against malware", "desc": "Protection against malware shall be implemented and supported by appropriate user awareness."},
    {"id": "8.8", "theme": "Technological Controls", "name": "Management of technical vulnerabilities", "desc": "Information about technical vulnerabilities of information systems being used shall be obtained, the organization's exposure to such vulnerabilities shall be evaluated and appropriate measures shall be taken."},
    {"id": "8.9", "theme": "Technological Controls", "name": "Configuration management", "desc": "Configurations, including security configurations, of hardware, software, services and networks shall be established, documented, implemented, monitored and reviewed."},
    {"id": "8.10", "theme": "Technological Controls", "name": "Information deletion", "desc": "Information stored in information systems, devices or in any other storage media shall be deleted when no longer required."},
    {"id": "8.11", "theme": "Technological Controls", "name": "Data masking", "desc": "Data masking shall be used in accordance with the organization’s topic-specific policy on access control and other related topic-specific policies, and business requirements."},
    {"id": "8.12", "theme": "Technological Controls", "name": "Data leakage prevention", "desc": "Data leakage prevention measures shall be applied to systems, networks and any other devices that process, store or transmit sensitive information."},
    {"id": "8.13", "theme": "Technological Controls", "name": "Information backup", "desc": "Backup copies of information, software and systems shall be maintained and regularly tested."},
    {"id": "8.14", "theme": "Technological Controls", "name": "Redundancy of information processing facilities", "desc": "Information processing facilities shall be implemented with sufficient redundancy to meet availability requirements."},
    {"id": "8.15", "theme": "Technological Controls", "name": "Logging", "desc": "Logs that record activities, exceptions, faults and other relevant events shall be produced, stored, protected and analysed."},
    {"id": "8.16", "theme": "Technological Controls", "name": "Monitoring activities", "desc": "Networks, systems and applications shall be monitored for anomalous behaviour and appropriate actions taken to evaluate potential information security incidents."},
    {"id": "8.17", "theme": "Technological Controls", "name": "Clock synchronization", "desc": "The clocks of information processing systems used by the organization shall be synchronized to approved time sources."},
    {"id": "8.18", "theme": "Technological Controls", "name": "Use of privileged utility programs", "desc": "The use of utility programs that can be capable of overriding system and application controls shall be restricted and tightly controlled."},
    {"id": "8.19", "theme": "Technological Controls", "name": "Installation of software on operational systems", "desc": "Procedures and measures shall be implemented to securely manage software installation on operational systems."},
    {"id": "8.20", "theme": "Technological Controls", "name": "Networks security", "desc": "Networks and network devices shall be secured, managed and controlled to protect information in systems and applications."},
    {"id": "8.21", "theme": "Technological Controls", "name": "Security of network services", "desc": "Security mechanisms, service levels and management requirements of network services shall be identified, implemented and monitored."},
    {"id": "8.22", "theme": "Technological Controls", "name": "Segregation of networks", "desc": "Groups of information services, users and information systems shall be segregated in the organization’s networks."},
    {"id": "8.23", "theme": "Technological Controls", "name": "Web filtering", "desc": "Access to external websites shall be managed to reduce exposure to malicious content."},
    {"id": "8.24", "theme": "Technological Controls", "name": "Use of cryptography", "desc": "Rules for the effective and acceptable use of cryptographic controls, including cryptographic key management, shall be defined and implemented."},
    {"id": "8.25", "theme": "Technological Controls", "name": "Secure development life cycle", "desc": "Rules for the secure development of software and systems shall be established and applied."},
    {"id": "8.26", "theme": "Technological Controls", "name": "Application security requirements", "desc": "Information security requirements shall be identified, specified and approved when developing or acquiring applications."},
    {"id": "8.27", "theme": "Technological Controls", "name": "Secure system architecture and engineering principles", "desc": "Principles for engineering secure systems shall be established, documented, maintained and applied to any information system development activities."},
    {"id": "8.28", "theme": "Technological Controls", "name": "Secure coding", "desc": "Secure coding principles shall be applied to software development."},
    {"id": "8.29", "theme": "Technological Controls", "name": "Security testing in development and acceptance", "desc": "Security testing processes shall be defined and implemented in the development life cycle."},
    {"id": "8.30", "theme": "Technological Controls", "name": "Outsourced development", "desc": "The organization shall direct, monitor and review the activities related to outsourced system development."},
    {"id": "8.31", "theme": "Technological Controls", "name": "Separation of development, test and production environments", "desc": "Development, testing and production environments shall be separated and secured."},
    {"id": "8.32", "theme": "Technological Controls", "name": "Change management", "desc": "Changes to information processing facilities and information systems shall be subject to change management procedures."},
    {"id": "8.33", "theme": "Technological Controls", "name": "Test information", "desc": "Test information shall be carefully selected, protected and managed."},
    {"id": "8.34", "theme": "Technological Controls", "name": "Protection of information systems during audit testing", "desc": "Audit tests and other assurance activities involving assessment of operational systems shall be planned and agreed between the tester and appropriate management."},
]
